import json, sys, datetime

path = sys.argv[1]
prev_ts = None
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            print("PARSE-ERROR", line[:200])
            continue
        ts = obj.get("timestamp")
        role = obj.get("role") or obj.get("type")
        delta = ""
        if ts and prev_ts:
            try:
                t1 = datetime.datetime.fromisoformat(ts.replace("Z","+00:00"))
                t0 = datetime.datetime.fromisoformat(prev_ts.replace("Z","+00:00"))
                secs = (t1-t0).total_seconds()
                if secs > 20:
                    delta = f"  [+{secs:.0f}s]"
            except Exception:
                pass
        if ts:
            prev_ts = ts
        msg = obj.get("message") or {}
        content = msg.get("content") if isinstance(msg, dict) else None
        summary_parts = []
        if isinstance(content, str):
            summary_parts.append(content[:300])
        elif isinstance(content, list):
            for c in content:
                if not isinstance(c, dict):
                    continue
                t = c.get("type")
                if t == "text":
                    summary_parts.append(("TEXT: " + c.get("text","")[:300]))
                elif t == "tool_use":
                    inp = json.dumps(c.get("input",{}))[:200]
                    summary_parts.append(f"TOOL_USE {c.get('name')}: {inp}")
                elif t == "tool_result":
                    cc = c.get("content")
                    if isinstance(cc, list):
                        cc = " ".join(x.get("text","")[:150] for x in cc if isinstance(x,dict))
                    summary_parts.append(f"TOOL_RESULT: {str(cc)[:200]}")
        if not summary_parts:
            continue
        print(f"--{role}{delta} ts={ts}")
        for s in summary_parts:
            print("   " + s.replace("\n"," "))

